CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,role ENUM('admin','owner','tenant') NOT NULL,name VARCHAR(100) NOT NULL,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,phone VARCHAR(20),status ENUM('active','suspended') DEFAULT 'active',must_change TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS rooms(id INT AUTO_INCREMENT PRIMARY KEY,room_no VARCHAR(20) UNIQUE NOT NULL,type VARCHAR(50),rent DECIMAL(10,2) NOT NULL,descr VARCHAR(255),status ENUM('vacant','reserved','occupied','maintenance') DEFAULT 'vacant',tenant_id INT NULL,water_last INT DEFAULT 0,elec_last INT DEFAULT 0,use_common TINYINT DEFAULT 1,use_wifi TINYINT DEFAULT 1,FOREIGN KEY(tenant_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS invoices(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT NOT NULL,tenant_id INT NOT NULL,month CHAR(7) NOT NULL,rent DECIMAL(10,2),water_units INT,elec_units INT,water DECIMAL(10,2),elec DECIMAL(10,2),total DECIMAL(10,2),common DECIMAL(10,2) DEFAULT 0,wifi DECIMAL(10,2) DEFAULT 0,water_prev INT,water_curr INT,elec_prev INT,elec_curr INT,status ENUM('unpaid','pending','paid','rejected') DEFAULT 'unpaid',slip VARCHAR(100),note VARCHAR(255),due DATE,paid_at DATETIME NULL,late_fee DECIMAL(10,2) NOT NULL DEFAULT 0,late_days INT NOT NULL DEFAULT 0,UNIQUE(room_id,month),FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(tenant_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS repairs(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT,tenant_id INT,item VARCHAR(100),descr TEXT,img VARCHAR(100),status ENUM('pending','in_progress','done') DEFAULT 'pending',cost DECIMAL(10,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS announcements(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150),body TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS settings(k VARCHAR(30) PRIMARY KEY,v VARCHAR(255)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(255),ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
INSERT IGNORE INTO settings VALUES('water_rate','18'),('elec_rate','8'),('promptpay','0812345678'),('dorm_name','สุขใจ เรสซิเดนซ์');
CREATE TABLE IF NOT EXISTS bookings(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT NOT NULL,tenant_id INT NOT NULL,rent DECIMAL(10,2),deposit DECIMAL(10,2),amount DECIMAL(10,2),slip VARCHAR(100),status ENUM('awaiting','pending','approved','rejected','cancelled') DEFAULT 'awaiting',note VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(tenant_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS room_images(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT NOT NULL,file VARCHAR(100) NOT NULL,FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
INSERT IGNORE INTO settings VALUES('common_fee','100'),('wifi_fee','100'),('pay_name',''),('bank_name',''),('bank_no','');
CREATE TABLE IF NOT EXISTS leases(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT NOT NULL,tenant_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,rent DECIMAL(10,2),deposit DECIMAL(10,2) DEFAULT 1000,status ENUM('active','ended') DEFAULT 'active',note VARCHAR(255),deposit_status ENUM('held','refunded','forfeited') NOT NULL DEFAULT 'held',deposit_settled_at DATETIME NULL,deposit_note VARCHAR(255) NULL,ended_at DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(tenant_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
